import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosBox } from "../../index";

/**
 * Vue's Box: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Box`; AsChild written by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Layout/Box",
  component: KozmosBox,
  parameters: {
    layout: "centered",
  },
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        // React's `className` is Vue's `class`.
        if (!SLOTS.includes(key))
          props[key === "className" ? "class" : key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosBox, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "This is a Box",
    className: "p-4 bg-theme-fill text-theme-fill-foreground rounded-control",
  },
};

/** React's AsChild: the Box's attributes drawn on its one child, a span. */
export const AsChild: Story = {
  render: () => ({
    components: { KozmosBox },
    template: `
      <KozmosBox as-child>
        <span class="p-4 bg-secondary text-secondary-foreground rounded-control">
          This is a Span rendered via Box asChild
        </span>
      </KozmosBox>
    `,
  }),
};
